+#!/usr/bin/env node
+'use strict';
+
+const { resolve, resolvePaths } = require('../src/index.js');
+
+const HELP = `Usage: nmr <request> [options]
+
+Resolve a module specifier the way Node's require() would.
+
+Options:
+  --from <path>  File or directory to resolve from (default: cwd)
+  --paths        Print every candidate directory Node would search
+  -h, --help     Show this help
+`;
+
+function main(argv) {
+  const args = argv.slice(2);
+  let from = process.cwd();
+  let paths = false;
+  const requests = [];
+
+  for (let i = 0; i < args.length; i += 1) {
+    const arg = args[i];
+    if (arg === '-h' || arg === '--help') {
+      process.stdout.write(HELP);
+      return;
+    }
+    if (arg === '--from') {
+      from = args[i + 1];
+      if (from === undefined) {
+        process.stderr.write('error: --from requires a path\n');
+        process.exitCode = 1;
+        return;
+      }
+      i += 1;
+      continue;
+    }
+    if (arg === '--paths') {
+      paths = true;
+      continue;
+    }
+    requests.push(arg);
+  }
+
+  if (requests.length === 0) {
+    process.stderr.write(HELP);
+    process.exitCode = 1;
+    return;
+  }
+
+  for (const request of requests) {
+    try {
+      const result = paths ? resolvePaths(request, from) : resolve(request, from);
+      if (result === null) {
+        process.stdout.write(`${request} is a builtin\n`);
+      } else if (Array.isArray(result)) {
+        process.stdout.write(`${result.join('\n')}\n`);
+      } else {
+        process.stdout.write(`${result}\n`);
+      }
+    } catch (error) {
+      process.stderr.write(`${error.message}\n`);
+      process.exitCode = 1;
+    }
+  }
+}
+
+main(process.argv);

