'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { createRequire, isBuiltin } = require('node:module');
const { pathToFileURL } = require('node:url');

/**
 * Normalize a file or directory into an absolute *file* path that can anchor a
 * `require` created with `module.createRequire`. createRequire uses the
 * dirname of its argument, so a directory must be given a synthetic child.
 */
function anchorFile(from) {
  const abs = path.resolve(from);

  let stats;
  try {
    stats = fs.statSync(abs);
  } catch {
    stats = null;
  }

  if (stats && stats.isFile()) return abs;
  if (stats && stats.isDirectory()) return path.join(abs, 'index.js');
  if (/[\\/]$/.test(from) || from === '.') return path.join(abs, 'index.js');
  return abs;
}

function requireFrom(from) {
  return createRequire(pathToFileURL(anchorFile(from)));
}

/**
 * Resolve a specifier exactly the way CommonJS `require.resolve` would, but
 * anchored at an arbitrary file or directory instead of the calling module.
 *
 * Builtins are returned unchanged (e.g. `fs`, `node:path`).
 *
 * @param {string} request Module specifier, relative path, or absolute path.
 * @param {string} [from=process.cwd()] File or directory to resolve from.
 * @returns {string} Absolute filesystem path, or the builtin id.
 */
function resolve(request, from = process.cwd()) {
  if (typeof request !== 'string' || request.length === 0) {
    throw new TypeError('request must be a non-empty string');
  }
  if (isBuiltin(request)) return request;
  return requireFrom(from).resolve(request);
}

/**
 * Every `node_modules` directory Node would search for a package, in order.
 * Mirrors `require.resolve.paths`; returns null for builtins.
 *
 * @param {string} request Module specifier.
 * @param {string} [from=process.cwd()] File or directory to resolve from.
 * @returns {string[]|null}
 */
function resolvePaths(request, from = process.cwd()) {
  if (isBuiltin(request)) return null;
  return requireFrom(from).resolve.paths(request);
}

/**
 * Resolve `request` from each anchor in order, returning the first hit.
 *
 * @param {string} request Module specifier.
 * @param {string|string[]} froms One or more anchor files/directories.
 * @returns {string}
 */
function resolveMany(request, froms) {
  const anchors = Array.isArray(froms) ? froms : [froms];
  let lastError;
  for (const from of anchors) {
    try {
      return resolve(request, from);
    } catch (error) {
      if (error.code !== 'MODULE_NOT_FOUND') throw error;
      lastError = error;
    }
  }
  if (lastError) throw lastError;
  throw new TypeError('resolveMany requires at least one anchor');
}

module.exports = { resolve, resolvePaths, resolveMany };

#!/usr/bin/env node
'use strict';

const { resolve, resolvePaths } = require('../src/index.js');

const HELP = `Usage: nmr <request> [options]

Resolve a module specifier the way Node's require() would.

Options:
  --from <path>  File or directory to resolve from (default: cwd)
  --paths        Print every candidate directory Node would search
  -h, --help     Show this help
`;

function main(argv) {
  const args = argv.slice(2);
  let from = process.cwd();
  let paths = false;
  const requests = [];

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(HELP);
      return;
    }
    if (arg === '--from') {
      from = args[i + 1];
      if (from === undefined) {
        process.stderr.write('error: --from requires a path\n');
        process.exitCode = 1;
        return;
      }
      i += 1;
      continue;
    }
    if (arg === '--paths') {
      paths = true;
      continue;
    }
    requests.push(arg);
  }

  if (requests.length === 0) {
    process.stderr.write(HELP);
    process.exitCode = 1;
    return;
  }

  for (const request of requests) {
    try {
      const result = paths ? resolvePaths(request, from) : resolve(request, from);
      if (result === null) {
        process.stdout.write(`${request} is a builtin\n`);
      } else if (Array.isArray(result)) {
        process.stdout.write(`${result.join('\n')}\n`);
      } else {
        process.stdout.write(`${result}\n`);
      }
    } catch (error) {
      process.stderr.write(`${error.message}\n`);
      process.exitCode = 1;
    }
  }
}

main(process.argv);

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const os = require('node:os');
const path = require('node:path');

const { resolve, resolvePaths, resolveMany } = require('../src/index.js');

const FIXTURES = path.join(__dirname, 'fixtures');
const APP = path.join(FIXTURES, 'app', 'index.js');
const APP_DIR = path.join(FIXTURES, 'app');

test('returns builtin ids untouched', () => {
  assert.equal(resolve('fs'), 'fs');
  assert.equal(resolve('node:path'), 'node:path');
});

test('resolves a relative file from a file anchor', () => {
  assert.equal(resolve('./helper', APP), path.join(APP_DIR, 'helper.js'));
});

test('resolves a relative file from a directory anchor', () => {
  assert.equal(resolve('./helper', APP_DIR), path.join(APP_DIR, 'helper.js'));
});

test('resolves a package through node_modules', () => {
  assert.equal(
    resolve('left-pad', APP),
    path.join(FIXTURES, 'node_modules', 'left-pad', 'index.js')
  );
});

test('honors a directory package.json "main" field', () => {
  assert.equal(resolve('./lib', APP), path.join(APP_DIR, 'lib', 'main.js'));
});

test('exposes the search paths Node would use', () => {
  const paths = resolvePaths('left-pad', APP);
  assert.ok(Array.isArray(paths));
  assert.ok(paths.includes(path.join(APP_DIR, 'node_modules')));
  assert.ok(paths.includes(path.join(FIXTURES, 'node_modules')));
  assert.equal(resolvePaths('fs', APP), null);
});

test('throws MODULE_NOT_FOUND with a helpful message', () => {
  assert.throws(
    () => resolve('does-not-exist-xyz', APP),
    (error) =>
      error.code === 'MODULE_NOT_FOUND' &&
      /does-not-exist-xyz/.test(error.message)
  );
});

test('resolveMany falls through to the first anchor that succeeds', () => {
  const missing = path.join(os.tmpdir(), 'nmr-missing-anchor', 'index.js');
  assert.equal(resolveMany('./helper', [missing, APP]), path.join(APP_DIR, 'helper.js'));
});

test('rejects non-string requests', () => {
  assert.throws(() => resolve(''), TypeError);
});

